            ((SQLServerInsertStatement) insertStatement).setWithSegment(withSegment);
        }
        if (insertStatement instanceof OpenGaussInsertStatement) {
            ((OpenGaussInsertStatement) insertStatement).setWithSegment(withSegment);
        }
    }

